//! The daemon's wire types: prost messages generated from
//! `proto/ctxloom/daemon/v1`. A `HandleSync` projection is the resource
//! message the matching `Get` returns (daemon.proto's header): a read model
//! answers its view as one of these (S32).
//!
//! Every message is also its proto3 JSON (ruling 146, OQ-21): serde impls
//! generated by pbjson-build, proto field names kept, a default left out,
//! an enum by its value's name, a 64-bit integer as a decimal string. The
//! well-known types the package uses are this crate's own
//! ([`google::protobuf`]), with their JSON mapping written by hand
//! (`wkt.rs`): a `Timestamp` RFC 3339 in UTC, a `Struct` the object itself
//! (its keys sorted), a `FieldMask` its paths in one string.

/// The generated package, nested as its proto package is.
pub mod ctxloom {
    pub mod daemon {
        // Generated: the request oneofs carry whole messages (a launch
        // beside a word), as the drafts define them.
        #[allow(clippy::large_enum_variant)]
        pub mod v1 {
            include!(concat!(env!("OUT_DIR"), "/json/ctxloom.daemon.v1.rs"));
            // Generated by pbjson-build.
            #[allow(
                clippy::all,
                clippy::pedantic,
                clippy::nursery,
                clippy::cognitive_complexity,
                missing_docs
            )]
            mod serde_impls {
                use super::*;
                include!(concat!(env!("OUT_DIR"), "/json/ctxloom.daemon.v1.serde.rs"));
            }
        }
    }
}

/// The well-known types the package uses, compiled here so that they carry
/// proto3 JSON (`wkt.rs`); each converts to and from prost-types' own.
pub mod google {
    pub mod protobuf {
        // Generated.
        #![allow(clippy::all, clippy::pedantic, clippy::nursery, missing_docs)]
        include!(concat!(env!("OUT_DIR"), "/json/google.protobuf.rs"));
    }
}

mod wkt;

/// `ctxloom.daemon.v1`.
pub use ctxloom::daemon::v1;

